    let u2 = fract(52.9829189 * fract(dot(frag.xy + vec2<f32>(23.0, 71.0) + shift * 1.3, vec2<f32>(0.06711056, 0.00583715))));
    let up = select(vec3<f32>(0.0, 1.0, 0.0), vec3<f32>(1.0, 0.0, 0.0), abs(N.y) > 0.9);
